INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1248110-che409', 'stk-hexane', 'CHE 409', 'info', '{"desc": "CHE 409 إمتداد لـCHE 309\nمتشابهين لحد كبير (أظن ان تقسيم الدرجات نفسه في الـ309 والله أعلم)\n\nوهذا رابط مفيد لتقييم CHE 309 ([فيذا](http://skfupm.kfupm.edu.sa/vb/showthread.php? p=1232012#post1232012))\n\nبشكل عام الكورس هذا بيتكلم عن:\n1. Unit Operations\nProcess Control (CHE 401) .2\nReaction Kinetics (CHE 402) .3\n\nالـ409 مقارنة بالـ309 أشوفها أصعب بشوي … وهذا لسبب واحد وهو جزء الـProcess Control وهذا الجزء هو أكثرهم تعقيدا لذا خذوا بالكم\n\nأخيرا … لا تفرطون في الكتاب , واعتبروه كـمرجع لكم مستقبلاً\nدعواتكم 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-409-chemical-engineering-laboratory-ii/120658/2", "user": "HeXaNe", "ts": 1374631846000, "tid": 120658, "pn": 2}}', 1374631846000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1318718-che409', 'stk-chemist', 'CHE 409', 'info', '{"desc": "الكتاب المقرر:\nCHE 409 Chemical Engineering Laboratory Manual II 2012\n\nتقييم الكتاب:\nأولا الكتاب غير محدث فيه تجربيتن درسناها من خارج الكتاب UO-1 & UO-2. وثانيا الكتاب فيه غموض وخاصه في الكالكوليشن تحس انك لازم تفك طلاسم قبل ماتسوي الكالكوليشن. فبصراحه أشوف انه غير واضح في هذه النقطة طبعا ما اتكلم عن كل التجارب ولكن اتكلم عن معظمها.\n\nالمواضيع التي يغطيها المقرر:\nهي امتداد لـ CHE 309 وتتكلم عن ثلاث أقسام وكل قسم فيه أربع تجارب:\n1) Unit Operation - CHE 306\n2) Process Control - CHE 401\n3) Reaction Kinetics - CHE 402\n\nالجزء الأول: Unit Operation\n\nUO-1 Double Effect Evaporator\nوتتكلم هذه التجربة عن الفرق بين استخدام مبخر واحد ( One evaporator ) واستخدام مبخرين ( Two evaporator ). وكيف أن التكلفة الاقتصادية تقل عند استخدام مبخرين لأن البخار من المبخر الأول يستخدم كمولد طاقه للمبخر الثاني وهكذا.\nUO-2 Continuous Distillation of Binary Mixture\nالهدف من هذه التجربة هي دراسة أبراج الفصل عمليا التي تم دراستها في CHE 306 وكيفية فصل المواد عن بعضها البعض مثل ماء وإيثانول. يتم في هذه التجربة أيضا التعرف على ( Reflux Ratio ) و Equilibrium Stages) ).\nUO-5 Cooling Tower\n**هي عبارة عن تبريد الماء بواسطة الهواء في (**Packed Column ). على فترات متفاوت نغير دفع الهواء بواسطة الكومبيوتر ونلاحظ الفرق.\nUO-8 Immiscible Liquid-Liquid Extraction\nالهدف من هذه التجربة وهي معرفه استخراج سائل من سائل بواسطة سائل 😆 **بشرط أن يكون السائل الأول غير قابل للذوبان في السائل الثاني. طبعا تتم هذه التجربة في (**spinning band micro- extraction column ).\n\nالجزء الثاني: Process Control\n\nPC-1 Dynamics of Stirred Tanks\nالهدف من هذه التجربة هو إجراء تغيرات عديدة على النظام من ( Positive step ) و ( Negative step ) و ( Impulse change ) ونلاحظ استجابة النظام لهذه المتغيرات المختلفة من خلال قياس ( Conductivity ) لكل Tank.\nPC-2 Time Constants of Thermocouples\nالهدف من هذه التجربة هي قياس الوقت لحساس الحرارة تحت ظروف مختلفة وكيف يؤثر ثابت الوقت على استجابة النظام.\nPC-3 Pressure Control\nهذي أصعب تجربة مرت علينا في هذا الكورس وإلى الآن ما فهمناها عدل. تتكلم هذه التجربة بشكل عام عن كيفية التحكم بضغط نظام ما بطرق مختلفة.\nPC-6 Temperature, Flow Rate and Level Control using Computer\nتتكلم هذه التجربة عن التحكم في الحرارة ومعدل التدفق وارتفاع السائل عن طريق الكومبيوتر. أيضا يتم دراسة بعض التغيرات المفاجئة على النظام وكيف يتعامل النظام مع هذه التغيرات المفاجئة.\n\nالجزء الثالث: Reaction Kinetics\n\nRK-3 Homogenous Continuous Stirred Tank Reactor\nالهدف من هذه التجربة هو التعرف على مفاعل ( CSTR ) وكيفيه عمله. أيضا التعرف على ( Steady state Conversion ) و ( Time Constant ) وغيرها.\nRK-4 Homogenous Tubular Reactor\nتتحدث هذه التجربة عن مفاعل ( PFR ) وكيفيه عمله والمقارنة بينه وبين ( CSTR ). وهي شبيه جدا بـ RK-3 ولكن المفاعل في هذه التجربة هو الاختلاف الوحيد بينهما.\nRK-5 Neutralization of Aqueous Solution of Acetic Acid\nتتكلم هذه التجربة عن ( Batch Reactor) وكيفيه عمله والفرق بينه وبين المفاعلات الأخرى. يتم في هذه التجربة تفاعل بين قاعدة وحمض لإنتاج ملح ويقاس تركيز المواد المتفاعلة بواسطة ( pH meter ).\nRK-6 Saponification of Ethyl Acetate with the Aid of Computer\nالهدف من هذه التجربة هي التعرف على التفاعل المكون للصابون الذي يتم في ( Batch Reactor ) بمساعدة الكومبيوتر.\n\nيتبع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-409-chemical-engineering-laboratory-ii/120658/3", "user": "Chemist", "ts": 1389607859000, "tid": 120658, "pn": 3}}', 1389607859000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p972850-che409', 'stk-user4221', 'CHE 409', 'info', '{"desc": "و عليكم السلام و رحمة الله و بركاته\n\nبالنسبة ل CHE 409 , CHE 495 ما أخذت هذه المواد.\n\nبالنسبة ل CHE 425, المادة عموما سهلة و بإمكانك أن تأخذ فيها درجة ممتازة. رأيي أن الدكتور عدنان العامر ممتاز في هذي المادة من ناحية قدرته غلى توصيل المعلومة ( ممتاز في الشرح), اختباراته تبين الطالب الفاهم من الحافظ, اختباراته تنقسم إلى شقين (Closed Book & Open Book); Closed book في السؤال الأول عبارة عن خمسة أسئلة اختيار من متعدد يكون مستواها في العادة متوسط مائل إلى الصعوبة, و هي التي يخطئ فيها كثير من الطلاب لأنها تحتاج أنك تكون فاهم و مذاكر كويس, أما الأسئلة الأخرى فهي عبارة عن أسئلة مقالية ذات مستوى سهل إلى متوسط و إجاباتها في الغالب لا تتعدى السطر الواحد و بعض الأحيان فقط كلمة, كما تأتي بعض الأسئلة كتعبئة جدول أو مسائل حسابية; هذا بالنسبة لل Closed book, أما بالنسبة لل Open Book, فإن الأسئلة دائما تكون مباشرة و عادة ما تأتي من Appendix B, حيث إنه يزخر بعدد وافر من طرق تصنيع المواد الكيميائية في المصانع ( إذا أخذت المادة راح تعرف أنا إيش قاعد أخربط:)), عموما الدكتور عدنان ممتاز و يعاملك كإبن لكنه في النهاية ما راح يعطيك أكثر من حقك. أما بالنسبة للدكتور بكر أمين, فما أعرف شيء عنه إلا أن المادة عنده سهالات و أنه مبسط المادة لأبعد حد و معدل اختباراته في الغالب أعلى من 70, و ياليت لو تسأل أحد الطلاب الذين درسوا عنده فسوف يفيدونك بشكل أكبر. و السلام عليكم و رحمة الله و بركاته.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-112/115051/200", "user": "user4221", "ts": 1327362930000, "tid": 115051, "pn": 200}}', 1327362930000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemist-che409', 'stk-chemist', 'CHE 409', 'doc', '{"docs": [{"id": "stk-dr-f118702", "n": "Dr. Umar Mehmood", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 409 Term 131\n\nالتحضير:\nمايحضر وما عنده مشكله إذا تأخرت 😆. وحبيب جدا جدا في مسأله التأخير. بس انتبه إذا جيت متأخر راح تطلع متأخر علشان تأخرك في آداء التجربه.\n\nطريقة الشرح:\nهو به شرح أصلا 😆. الرجال للأمانه مو فاهم شي وإذا ابتلش في أي خطوه نادى التكنشن وقال كيف كذا وكيف كذا 😐. يعني بصراحه وجوده زي عدمه. في بعض المرات استغرب كيف الرجال معه ماستر. أما في الأوفس آور حقت الكالكوليشن فهو أفضل بكثير من حاله في اللاب تحس انه يشرح ويبذل قصار جهده لكي يفهمك الحسابات ولكن أيضا في شرحه مشكله وتحس في بعض المرات انه يسلك لك وهو مايدري وش السالفه علشان تمشي 😆 المهم وبإختصار شرحه من جنبها 😆.\n\nتصحيح الريبورتات:\nأول شي هو حبيب جديد فما فيه مشكله عنده تأخر تسليم الريبورت. أما التصحيح فتحس انه يهتم بالقواعد اللغة الإنجليزية أكثر من اهتمامه بالنتائج والإستنتاجات. ففي الريبورت الأول عطاني 2.5 من 4 قلت له ليه قال Grammatical Mistakes 😐. ومن بعدها حسنت كتابتي وتفاديت الأخطاء النحويه وصار يعطيني 4 من 4 في كل تقرير.\n\nOral Presentation:\nمتساهل في البريزنتيشن وأقل واحد أعطاه 7 من 8. في نصف البريزنتيشن يسأل أسئله صعبه عن التجربه يشوف انت فاهم التجربه صح أو لا. بإختصار سهالات ولا تشيل هم.\n\nالكويزات:\nيعطيك الكويز بعد كل تجربه ويقول تقدر وبكل آريحيه تتناقش أنت وخويك في حل الكويز. فكوزاته كانت في بدايه الأمر سهله ولكن من يوم انتقلنا إلى قسم RK صار كوزاته حريقه وريتن وبعدين صارت متوسطه يوم انتقلنا لقسم PC . أنا احس ان كوزاته صار لها سنين ما يغيرها علشان كذا كانت متنوعه ومتفاوت الصعوبه طول الفصل.\n\nالصوت:\nهو باكستاني فراح تتعود على اللهجه وصوته كويس ومفهوم.\n\nمميزاته:\nحبيب جدا جدا جدا وراح أتعب وأنا اقول جدا جدا 😆 ومتساهل ومتعاون إلى أقصى درجه ممكن تتصورها.\n\nسلبياته:\nأكبر سلبيه فيه انه مو فاهم الماده يعني أعطيه 30 % كالنسبه فهمه للماده.\n\nالقريد النهائي:\nأعطيه B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1318525-che409", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/umar-mehmood/118702/4", "user": "Chemist", "ts": 1389540985000, "tid": 118702, "pn": 4}}]}', 1389540985000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-unlucky-che409', 'stk-unlucky', 'CHE 409', 'doc', '{"docs": [{"id": "stk-dr-f182615", "n": "Dr. Yahya Gambo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE409\nبنود التقييم :\n\nطريقة الشرح : شرح للتجربة ومعه شخصين وكل واحد يشرح تجربة\nالكويزات : كويزاته متوسطة وتحتاج ونفس نظام أسئلة الفاينل\nالمياجر: مافيه\nالفاينلات : كومن وصعب\nالقريد النهائي: B\nالصوت: جيد\nإضافات : الدكتور حبيب جدًا ومحترم ومتعاون مع الطلاب لكن فيه عيوب كثيرة، أولها أنه يطول التجربة أكثر من اللازم وعادي يشرح لك الداتا اناليسس ساعة كاملة والطبيعي انك تطلع ٣:٣٠-٤ وهذا شيء سيء نوعًا ما.\nالسلبية الكبرى هي انه ما يعطي فيدباك أبدًا عكس الدكاترة الباقين، يعني تخيل ١٢ ريبورت وكويزات يخلص الفاينل وأنت ما تدري كم أخذت فيها + اذا عطاك وعد دايم يخلف البرزنتيشن لمدة أسبوع متواصل وكل يوم يقول يالله قدموا ويسحب.\nالادمي لكيع لكن حبيب.\nالB هذي لانه محترم وشرحه كويس فقط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534524-che409", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yahya-gambo/182615/2", "user": "Unlucky", "ts": 1654001484000, "tid": 182615, "pn": 2}}]}', 1654001484000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
